import{_ as i,o as s,c as a,ak as n}from"./chunks/framework.BRmknyjl.js";const o="/projects/NexArm/en/ros-version/assets/image1.CxO1fP9V.webp",e="data:image/png;base64,",r="/projects/NexArm/en/ros-version/assets/image3.BGMBb6hX.webp",l="/projects/NexArm/en/ros-version/assets/image1.BizDR_t1.webp",p="/projects/NexArm/en/ros-version/assets/image2.BIXahxlo.webp",c="/projects/NexArm/en/ros-version/assets/image3.CTs8r2hK.webp",h="/projects/NexArm/en/ros-version/assets/image4.BGdx7wLB.webp",g="/projects/NexArm/en/ros-version/assets/image5.DtBq-Rh_.webp",d="/projects/NexArm/en/ros-version/assets/image6.vxWRKoOU.webp",m="/projects/NexArm/en/ros-version/assets/image7.33eqsUYG.webp",u="/projects/NexArm/en/ros-version/assets/image4.DSIaqQAE.webp",k="/projects/NexArm/en/ros-version/assets/image5.NKwlHcK9.webp",b="/projects/NexArm/en/ros-version/assets/image6.DRRPk-wL.webp",w="/projects/NexArm/en/ros-version/assets/image7.BuEYlpaa.webp",y="/projects/NexArm/en/ros-version/assets/image8.JkLusM9H.webp",v="/projects/NexArm/en/ros-version/assets/image9.CJSUd4CU.webp",f="/projects/NexArm/en/ros-version/assets/image10.T2AOPb-H.webp",C="/projects/NexArm/en/ros-version/assets/image11.LdajGd1t.webp",A="/projects/NexArm/en/ros-version/assets/image12.CwAzVk2u.webp",F="/projects/NexArm/en/ros-version/assets/image13.D8pwfRYH.webp",x="/projects/NexArm/en/ros-version/assets/image14.D4xqwv5X.webp",_="/projects/NexArm/en/ros-version/assets/image15.C-iBMj-Y.webp",T="/projects/NexArm/en/ros-version/assets/image16.KTfnTmbG.webp",E="/projects/NexArm/en/ros-version/assets/image17.DBilnGvf.webp",O="/projects/NexArm/en/ros-version/assets/image18.D5-sjBWo.webp",B="/projects/NexArm/en/ros-version/assets/image19.CUHZhr55.webp",I="/projects/NexArm/en/ros-version/assets/image20.CHBgoTyC.webp",S="/projects/NexArm/en/ros-version/assets/image21.PknjtJmB.webp",P="/projects/NexArm/en/ros-version/assets/image22.CyclPczy.webp",z="/projects/NexArm/en/ros-version/assets/image23.DuJz_KhX.webp",q="/projects/NexArm/en/ros-version/assets/image24.BT1pN2Ob.webp",N="/projects/NexArm/en/ros-version/assets/image25.BKaZM70D.webp",j="/projects/NexArm/en/ros-version/assets/image26.BIr2Gbt3.webp",G=JSON.parse('{"title":"11. OpenClaw Practical Tutorial","description":"","frontmatter":{},"headers":[],"relativePath":"docs/11. OpenClaw Practical Tutorial.md","filePath":"docs/11. OpenClaw Practical Tutorial.md"}'),M={name:"docs/11. OpenClaw Practical Tutorial.md"};function R(J,t,Q,K,U,D){return s(),a("div",null,[...t[0]||(t[0]=[n('<h1 id="_11-openclaw-practical-tutorial" tabindex="-1">11. OpenClaw Practical Tutorial <a class="header-anchor" href="#_11-openclaw-practical-tutorial" aria-label="Permalink to &quot;11. OpenClaw Practical Tutorial&quot;">​</a></h1><p id="p11-1"></p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>The robot comes pre-configured with OpenClaw and related function packages from the factory. Follow &#39;Section 11.1 Preparation&#39; to import and compile them for initial setup. If errors or incompatibility issues arise during subsequent feature operations, refer to &#39;Section 11.1 Preparation&#39; to re-import the provided backup resource files and skills into the designated directories and recompile them. Proceed with the tutorial operations once compilation succeeds.</strong></p></div><h2 id="_11-1-preparation" tabindex="-1">11.1 Preparation <a class="header-anchor" href="#_11-1-preparation" aria-label="Permalink to &quot;11.1 Preparation&quot;">​</a></h2><p>Prior to running feature programs, the OpenClaw resource files must be moved into the corresponding directory.</p><ol><li><p>Connect to the robot remotely using NoMachine to access the system desktop.</p></li><li><p>Drag <strong>openclaw_resource.zip</strong> from <a href="https://drive.google.com/drive/folders/1Q-gB8Djl2TiUx7MrT8ogw9tLGD_e6IVd?usp=sharing" target="_blank" rel="noreferrer">OpenClaw Resource Folder</a> onto the desktop.</p></li></ol><img loading="lazy" height="561" width="1066" src="'+o+'" class="common_img" style="width:900px;"><ol start="3"><li><p>Click the command-line terminal icon <img loading="lazy" height="52" width="58" src="'+e+'" class="inline-icon" style="width:40px;"> on the left side of the system interface to launch the terminal.</p></li><li><p>Enter the command to extract the archive to the corresponding path:</p></li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">unzip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Desktop/openclaw_resource.zip</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span></span></code></pre></div><ol start="5"><li>Enter the command to navigate into the folder:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> openclaw_resource</span></span></code></pre></div><ol start="6"><li>Enter the command to execute the deployment script:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">zsh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deploy.sh</span></span></code></pre></div><ol start="7"><li>Enter <strong>y</strong> continuously for subsequent prompts to proceed with the configuration.</li></ol><img loading="lazy" height="520" width="881" src="'+r+'" class="common_img" style="width:800px;"><ol start="8"><li><p>After executing the script, previous backups of <strong>IDENTITY.md</strong>, <strong>MEMORY.md</strong>, and <strong>skills</strong> are preserved in the <strong>backup.20260408_111805</strong> folder, which can be viewed with the <code>ls</code> command.</p></li><li><p>Enter the command in the terminal to navigate to the workspace and compile the <strong>openclaw_controller</strong> package:</p></li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/ros2_ws/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">colcon</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --event-handlers</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  console_direct+</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --cmake-args</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -DCMAKE_BUILD_TYPE=Release</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --symlink-install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --packages-select</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> openclaw_controller</span></span></code></pre></div><ol start="10"><li>After compilation completes, enter the command to refresh environment variables:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">source</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.zshrc</span></span></code></pre></div><p id="p11-2"></p><h2 id="_11-2-large-model-api-key-acquisition-and-configuration" tabindex="-1">11.2 Large Model API Key Acquisition and Configuration <a class="header-anchor" href="#_11-2-large-model-api-key-acquisition-and-configuration" aria-label="Permalink to &quot;11.2 Large Model API Key Acquisition and Configuration&quot;">​</a></h2><p>When deploying OpenClaw on the robot, the agent model within the Agent framework must first be configured. This procedure requires obtaining a large language model API key and entering it into the corresponding configuration file.</p><p>OpenClaw natively supports multiple large models, including DeepSeek, MiniMax, OpenAI, Qwen, and Google. This guide demonstrates configuration using OpenAI as the primary example. If selecting an alternative model, search online to obtain the corresponding API key and populate it into the configuration file.</p><h3 id="_11-2-1-openai-large-model-api-key-acquisition" tabindex="-1">11.2.1 OpenAI Large Model API Key Acquisition <a class="header-anchor" href="#_11-2-1-openai-large-model-api-key-acquisition" aria-label="Permalink to &quot;11.2.1 OpenAI Large Model API Key Acquisition&quot;">​</a></h3><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>This section covers registering on the official OpenAI website and obtaining a large model API key.</strong></p></div><ol><li>Copy the URL: <a href="https://platform.openai.com/docs/overview" target="_blank" rel="noreferrer">https://platform.openai.com/docs/overview</a>, open the OpenAI webpage, and click <strong>Sign up</strong> in the upper-right corner to open the registration page.</li></ol><img loading="lazy" height="52" width="343" class="common_img" src="'+l+'" style="width:400px;"><ol start="2"><li>Follow the on-screen prompts to register and log in using a Google, Microsoft, or Apple account.</li></ol><img loading="lazy" height="566" width="726" class="common_img" src="'+p+'" style="width:600px;"><ol start="3"><li>Click the settings button, select <strong>Billing</strong>, and click <strong>Payment methods</strong> to link a payment method. Add funds to purchase tokens.</li></ol><img loading="lazy" height="54" width="458" class="common_img" src="'+c+'"><img loading="lazy" height="403" width="1474" class="common_img" src="'+h+'" style="width:700px;"><ol start="4"><li>After completing the setup, click <strong>API keys</strong>, then click <strong>Create new secret key</strong>. Complete the form according to the prompts and save the generated key securely for subsequent use.</li></ol><img loading="lazy" height="375" width="194" class="common_img" src="'+g+'"><img loading="lazy" height="184" width="1701" class="common_img" src="'+d+'" style="width:700px;"><img loading="lazy" height="485" width="443" class="common_img" src="'+m+'" style="width:500px;"><ol start="5"><li>This completes the key generation and account setup for the large model. This API key will be utilized in subsequent lessons.</li></ol><h3 id="_11-2-2-api-key-configuration" tabindex="-1">11.2.2 API Key Configuration <a class="header-anchor" href="#_11-2-2-api-key-configuration" aria-label="Permalink to &quot;11.2.2 API Key Configuration&quot;">​</a></h3><ol><li><p>The robot must maintain network connectivity, configured either in STA local area network mode or in AP direct connection mode with an Ethernet cable attached.</p></li><li><p>Connect to the robot using the NoMachine remote desktop tool to access the system interface, then click the terminal icon <img loading="lazy" height="52" width="58" src="'+e+'" class="inline-icon" style="width:60px;"> on the left taskbar to open a terminal window.</p></li></ol><img loading="lazy" height="463" width="739" src="'+u+'" class="common_img" style="width:600px;"><ol start="3"><li>Enter the command in the terminal to configure OpenClaw:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openclaw</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span></span></code></pre></div><ol start="4"><li>Select <strong>Local (this machine)</strong> and press <strong>Enter</strong>.</li></ol><img loading="lazy" height="368" width="913" src="'+k+'" class="common_img" style="width:800px;"><ol start="5"><li>Select <strong>Model</strong> to configure the model settings and press <strong>Enter</strong>.</li></ol><img loading="lazy" height="274" width="917" src="'+b+'" class="common_img" style="width:800px;"><ol start="6"><li>Select <strong>OpenAI</strong> and press <strong>Enter</strong>.</li></ol><img loading="lazy" height="578" width="912" src="'+w+'" class="common_img" style="width:800px;"><ol start="7"><li>Select <strong>OpenAI API key</strong> and press <strong>Enter</strong>.</li></ol><img loading="lazy" height="102" width="560" src="'+y+'" class="common_img" style="width:800px;"><ol start="8"><li>Paste the copied API key here.</li></ol><img loading="lazy" height="98" width="914" src="'+v+'" class="common_img" style="width:800px;"><ol start="9"><li>Select <strong>openai/gpt-5.4</strong> or another appropriate model and press <strong>Enter</strong>.</li></ol><img loading="lazy" height="769" width="907" src="'+f+'" class="common_img" style="width:800px;"><ol start="10"><li>The model configuration is now complete.</li></ol><img loading="lazy" height="166" width="921" src="'+C+'" class="common_img" style="width:800px;"><p id="p11-3"></p><h2 id="_11-3-telegram-application-configuration" tabindex="-1">11.3 Telegram Application Configuration <a class="header-anchor" href="#_11-3-telegram-application-configuration" aria-label="Permalink to &quot;11.3 Telegram Application Configuration&quot;">​</a></h2><h3 id="_11-3-1-configuring-telegram" tabindex="-1">11.3.1 Configuring Telegram <a class="header-anchor" href="#_11-3-1-configuring-telegram" aria-label="Permalink to &quot;11.3.1 Configuring Telegram&quot;">​</a></h3><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><ul><li><p><strong>Operations can be performed using either the Telegram app or the web version, with the web version demonstrated in this tutorial.</strong></p></li><li><p><strong>Ensure an active, accessible Telegram account is ready.</strong></p></li></ul></div><p>Telegram Web URL: <a href="https://web.telegram.org/k/" target="_blank" rel="noreferrer">https://web.telegram.org/k/</a></p><p>Step 1: Log in to Telegram using the app QR code scanner or by entering the phone number and SMS verification code.</p><img loading="lazy" height="717" width="1684" src="'+A+'" class="common_img" style="width:800px;"><p>Step 2: Search for <strong>BotFather</strong> in the top-left search bar of Telegram, then click the officially verified account with the blue checkmark badge to start a chat.</p><img loading="lazy" height="235" width="424" src="'+F+'" class="common_img" style="width:600px;"><p>Step 3: Enter and send <strong>/newbot</strong> in the chat window to create a bot and obtain the Token. Note that the bot username must end with <strong>_bot</strong>.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>Once created, a Token will be provided. Store it securely without public exposure, as it is required for subsequent OpenClaw configuration.</strong></p></div><img loading="lazy" height="952" width="1259" src="'+x+'" class="common_img" style="width:600px;"><img loading="lazy" height="592" width="1049" src="'+_+'" class="common_img" style="width:600px;"><h3 id="_11-3-2-connecting-openclaw-to-telegram-plugin" tabindex="-1">11.3.2 Connecting OpenClaw to Telegram Plugin <a class="header-anchor" href="#_11-3-2-connecting-openclaw-to-telegram-plugin" aria-label="Permalink to &quot;11.3.2 Connecting OpenClaw to Telegram Plugin&quot;">​</a></h3><p>Once Telegram preparation is complete, return to the system environment to configure OpenClaw.</p><p>Step 1: Modify the OpenClaw runtime configuration to enable the Telegram plugin:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openclaw</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> channels.telegram.enabled</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> true</span></span></code></pre></div><img loading="lazy" height="25" width="853" src="'+T+'" class="common_img" style="width:800px;"><p>Step 2: Write the Telegram bot Token into the OpenClaw configuration:</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">openclaw config set channels.telegram.botToken </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;BOT_TOKEN&quot;</span></span></code></pre></div><img loading="lazy" height="26" width="1234" src="'+E+'" class="common_img" style="width:800px;"><p>Step 3: Start the OpenClaw gateway service:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openclaw</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gateway</span></span></code></pre></div><img loading="lazy" height="27" width="683" src="'+O+'" class="common_img" style="width:800px;"><p>Step 4: In the BotFather chat window, click the indicated link to open the newly created bot chat, then click <strong>START</strong>.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>The <code>openclaw gateway</code> command must be launched in the terminal before clicking &#39;START` in Telegram. Otherwise, no pairing code will be generated.</strong></p></div><img loading="lazy" height="539" width="816" src="'+B+'" class="common_img" style="width:700px;"><img loading="lazy" height="951" width="1257" src="'+I+'" class="common_img" style="width:700px;"><p>Step 5: During the initial conversation, the Telegram bot sends a pairing code. Execute the command below in the terminal to complete the pairing.</p><img loading="lazy" height="329" width="954" src="'+S+'" class="common_img" style="width:700px;"><p>Step 6: Open a new terminal window and execute the following command. Note that <code>&lt;code&gt;</code> in the command must be replaced with the <strong>pairing code</strong> received in Telegram, without typing the <code>&lt;&gt;</code> characters:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openclaw</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pairing</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> approve</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> telegram</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">cod</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><img loading="lazy" height="26" width="870" src="'+P+'" class="common_img" style="width:800px;"><p>Step 7: Once the command executes successfully, initiate a conversation with the bot connected to OpenClaw in Telegram. If the Telegram bot responds intelligently, OpenClaw integration with Telegram is confirmed. Send a minimal test message, such as <strong>hello</strong>, to verify.</p><img loading="lazy" height="126" width="725" src="'+z+'" class="common_img" style="width:700px;"><p>The integration and deployment of <strong>OpenClaw</strong> with Telegram are now complete.</p><p id="p11-4"></p><h2 id="_11-4-openclaw-basic-applications" tabindex="-1">11.4 OpenClaw Basic Applications <a class="header-anchor" href="#_11-4-openclaw-basic-applications" aria-label="Permalink to &quot;11.4 OpenClaw Basic Applications&quot;">​</a></h2><h3 id="_11-4-2-openclaw-camera-feed-recognition" tabindex="-1">11.4.2 OpenClaw Camera Feed Recognition <a class="header-anchor" href="#_11-4-2-openclaw-camera-feed-recognition" aria-label="Permalink to &quot;11.4.2 OpenClaw Camera Feed Recognition&quot;">​</a></h3><p>Once the program starts, entering natural language text prompts OpenClaw to analyze the real-time camera feed and save the captured image locally. Example prompts include <strong>Take a photo</strong>, <strong>Take a look</strong>, or <strong>Describe what is in view</strong>. Through OpenClaw skills, incoming tasks are matched with registered skill descriptions, followed by subscribing to the ROS 2 camera image topic. Upon executing the task, OpenClaw invokes the configured large model via Agent to generate descriptive text and deliver a response.</p><h4 id="_11-4-2-1-preparation" tabindex="-1">11.4.2.1 Preparation <a class="header-anchor" href="#_11-4-2-1-preparation" aria-label="Permalink to &quot;11.4.2.1 Preparation&quot;">​</a></h4><ul><li><strong>Preparation</strong></li></ul><p>Refer to the <a href="https://wiki.hiwonder.com/projects/NexArm/en/ros-version/docs/10.%20Large%20AI%20Model%20Courses.html#_10-1-3-api-configuration" target="_blank" rel="noreferrer">1. Tutorials / 10. Large AI Model Courses / 10.1.3 API Configuration</a> tutorial to configure the API key.</p><p>Reference Tutorial: <a href="#p11-1">11.1 Preparation</a></p><ul><li><strong>Configure Large Model API Key</strong></li></ul><p>Reference Tutorial: <a href="#p11-2">11.2 Large Model API Key Acquisition and Configuration</a></p><ul><li><strong>Configure Telegram</strong></li></ul><p>Reference Tutorial: <a href="#p11-3">11.3 Telegram Application Configuration</a></p><h4 id="_11-4-2-2-feature-steps" tabindex="-1">11.4.2.2 Feature Steps <a class="header-anchor" href="#_11-4-2-2-feature-steps" aria-label="Permalink to &quot;11.4.2.2 Feature Steps&quot;">​</a></h4><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><ul><li><p><strong>Command input is strictly case-sensitive and space-sensitive.</strong></p></li><li><p><strong>The robot must maintain network connectivity, configured either in STA local area network mode or in AP direct connection mode with an Ethernet cable attached.</strong></p></li><li><p><strong>Before operating the robotic arm, firmly secure the robotic arm base to the tabletop or a stable platform using a G clamp. Operating the arm induces oscillation and inertial forces. Operating without proper clamping can cause the device to tip over, fall, or sustain damage, posing safety hazards.</strong></p></li></ul></div><ol><li><p>Click the terminal icon <img loading="lazy" height="52" width="58" src="'+e+'" class="inline-icon" style="width:60px;"> on the left side of the system interface to open the command line.</p></li><li><p>Enter the command to stop the app auto-start service:</p></li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">~</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/.stop_ros.sh</span></span></code></pre></div><ol start="3"><li>Enter the command and press <strong>Enter</strong> to enable robot hardware control, which also initializes the camera feed:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ros2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> launch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> openclaw_controller</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> openclaw_object_transport.launch.py</span></span></code></pre></div><img loading="lazy" height="408" width="641" src="'+q+'" class="common_img" style="width:600px;"><ol start="4"><li>Open a new terminal, enter the command, and press <strong>Enter</strong> to launch the OpenClaw service. Skip this step if the service is already running:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openclaw</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gateway</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span></span></code></pre></div><ol start="5"><li>Open another new terminal, enter the command, and press <strong>Enter</strong> to open the TUI window for dispatching commands:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openclaw</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tui</span></span></code></pre></div><ol start="6"><li>In the TUI window or the Telegram app chat interface, enter the command: <strong>Take a photo, describe what is visible, summarize it, and report where it is saved</strong>, then press <strong>Enter</strong> to initiate visual recognition.</li></ol><img loading="lazy" height="40" width="928" src="'+N+'" class="common_img" style="width:900px;"><ol start="7"><li>After a brief wait, OpenClaw delivers a text description of the current visual scene, saves the image, and displays the file storage path.</li></ol><img loading="lazy" src="'+j+'" class="common_img" style="width:900px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>The response is automatically generated by the large language model. Semantic accuracy is maintained, while the specific phrasing and wording exhibit natural variability.</strong></p></div><ol start="8"><li><p>Once the output illustrated above appears in the TUI window, the current conversational turn is complete. Subsequent control instructions can be entered to initiate the next interaction.</p></li><li><p>To explore other basic applications, continue entering commands as described in the corresponding tutorials. To switch to integrated applications, navigate to the final terminal window opened in Step 5 and press <strong>Ctrl+C</strong> to terminate robot hardware control. If termination does not occur immediately, press the shortcut repeatedly. If the process remains unresponsive, open a new terminal and run the cleanup script to terminate all ROS nodes:</p></li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">~</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/.stop_ros.sh</span></span></code></pre></div><ol start="10"><li>To completely shut down the OpenClaw feature, press <strong>Ctrl+C</strong> in each open terminal window.</li></ol><h4 id="_11-4-2-3-program-outcome" tabindex="-1">11.4.2.3 Program Outcome <a class="header-anchor" href="#_11-4-2-3-program-outcome" aria-label="Permalink to &quot;11.4.2.3 Program Outcome&quot;">​</a></h4><p>Once the feature is running, custom text instructions can be sent via the TUI window or the Telegram app chat, prompting OpenClaw to return a detailed textual analysis of the real-time camera scene.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>Actual performance varies depending on the selected large model, including command execution latency, response time, and the alignment between the generated output and the prompt.</strong></p></div><h3 id="_11-5-2-openclaw-smart-home-assistant" tabindex="-1">11.5.2 OpenClaw + Smart Home Assistant <a class="header-anchor" href="#_11-5-2-openclaw-smart-home-assistant" aria-label="Permalink to &quot;11.5.2 OpenClaw + Smart Home Assistant&quot;">​</a></h3><p>Once the program starts, custom text commands can be entered to command the robot to perform sorting and handling tasks, such as <strong>Sort the items into the storage boxes of matching colors</strong>. Through OpenClaw skills, incoming tasks are matched with skill descriptions, followed by publishing ROS 2 messages or service requests to command robotic arm gripping. Upon completing the task, OpenClaw invokes the configured large model via Agent to generate descriptive text and return a response.</p><h4 id="_11-5-2-1-preparation" tabindex="-1">11.5.2.1 Preparation <a class="header-anchor" href="#_11-5-2-1-preparation" aria-label="Permalink to &quot;11.5.2.1 Preparation&quot;">​</a></h4><ul><li><strong>Preparation</strong></li></ul><p>Refer to the <a href="https://wiki.hiwonder.com/projects/NexArm/en/ros-version/docs/10.%20Large%20AI%20Model%20Courses.html#_10-1-3-api-configuration" target="_blank" rel="noreferrer">1. Tutorials / 10. Large AI Model Courses / 10.1.3 API Configuration</a> tutorial to configure the API key.</p><p>Reference Tutorial: <a href="#p11-1">11.1 Preparation</a></p><ul><li><strong>Configure Large Model API Key</strong></li></ul><p>Reference Tutorial: <a href="#p11-2">11.2 Large Model API Key Acquisition and Configuration</a></p><ul><li><strong>Configure Telegram</strong></li></ul><p>Reference Tutorial: <a href="#p11-3">11.3 Telegram Application Configuration</a></p><p id="p11-5-2-2"></p><h4 id="_11-5-2-2-feature-steps" tabindex="-1">11.5.2.2 Feature Steps <a class="header-anchor" href="#_11-5-2-2-feature-steps" aria-label="Permalink to &quot;11.5.2.2 Feature Steps&quot;">​</a></h4><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><ul><li><p><strong>Command input is strictly case-sensitive and space-sensitive.</strong></p></li><li><p><strong>The robot must maintain network connectivity, configured either in STA local area network mode or in AP direct connection mode with an Ethernet cable attached.</strong></p></li><li><p><strong>Before operating the robotic arm, firmly secure the robotic arm base to the tabletop or a stable platform using a G clamp. Operating the arm induces oscillation and inertial forces. Operating without proper clamping can cause the device to tip over, fall, or sustain damage, posing safety hazards.</strong></p></li></ul></div><ol><li><p>Click the terminal icon <img loading="lazy" height="52" width="58" src="'+e+'" class="inline-icon" style="width:60px;"> on the left side of the system interface to open the command line.</p></li><li><p>Enter the command to stop the app auto-start service:</p></li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">~</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/.stop_ros.sh</span></span></code></pre></div><ol start="3"><li>Enter the command and press <strong>Enter</strong> to start robot hardware control:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ros2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> launch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> openclaw_controller</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> openclaw_object_transport.launch.py</span></span></code></pre></div><ol start="4"><li>Open a new terminal, enter the command, and press <strong>Enter</strong> to start the OpenClaw service. Skip this step if the service is already running:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openclaw</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gateway</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span></span></code></pre></div><ol start="5"><li>Open another new terminal, enter the command, and press <strong>Enter</strong> to open the TUI window for sending commands:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openclaw</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tui</span></span></code></pre></div><ol start="6"><li><p>In the TUI window or the Telegram app chat interface, enter the command: <strong>Sort the items into the storage boxes of matching colors</strong>, then press <strong>Enter</strong> to execute automated handling.</p></li><li><p>After waiting for a moment, the robotic arm grips the blocks and places them into the designated locations, followed by generating a confirmation text response in the TUI window.</p></li></ol><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>The response is automatically generated by the large language model. Semantic accuracy is maintained, while the specific phrasing and wording exhibit natural variability.</strong></p></div><ol start="8"><li><p>When the output shown above appears in the TUI window, the current conversational turn is complete. Subsequent control instructions can be entered to initiate the next interaction.</p></li><li><p>To explore other basic applications, continue entering commands as described in the corresponding tutorials. To switch to integrated applications, navigate to the final terminal window opened in Step 5 and press <strong>Ctrl+C</strong> to terminate robot hardware control. If termination does not occur immediately, press the shortcut repeatedly. If the process remains unresponsive, open a new terminal and run the cleanup script to terminate all ROS nodes:</p></li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">~</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/.stop_ros.sh</span></span></code></pre></div><ol start="10"><li>To completely shut down the OpenClaw feature, press <strong>Ctrl+C</strong> in each open terminal window.</li></ol><h4 id="_11-5-2-3-program-outcome" tabindex="-1">11.5.2.3 Program Outcome <a class="header-anchor" href="#_11-5-2-3-program-outcome" aria-label="Permalink to &quot;11.5.2.3 Program Outcome&quot;">​</a></h4><p>Once the feature is running, custom text instructions can be sent via the TUI window or the Telegram app chat, directing the robot to perform object placement.</p>',154)])])}const H=i(M,[["render",R]]);export{G as __pageData,H as default};
